-- The search of an assistance operator by the last 4 digits of the phone (only with a part of the name or the birth date, only among its own insured persons): a separate HMAC of the tail, so the full phone HMAC stays unusable for a partial search.
-- Generated by scripts/gen-schema.mjs from packages/domain/src/store/sql/migrationsPhoneTail.ts. Do not edit by hand:
-- change the TypeScript source and run `node scripts/gen-schema.mjs`.

-- HMAC-SHA-256 (the PII HMAC key of the API) of `tail4:<last 4 digits>`: 10 000 possible values, so it narrows a search
-- that must also match the name or the birth date; never shown. A filter on it needs the column's select privilege (as
-- phone_hmac): the rows stay those of the person's RLS, and without the API's key the value says nothing.
alter table public.insured add column phone_tail_hmac bytea;
create index insured_phone_tail_idx on public.insured (phone_tail_hmac) where phone_tail_hmac is not null;
grant select (phone_tail_hmac) on public.insured to authenticated;
comment on column public.insured.phone_tail_hmac is 'HMAC of the last 4 digits of the phone (tail4:NNNN): the assistance search together with a part of the name or the birth date.';

-- Every such search is audited.
alter table public.audit_log drop constraint audit_log_action_check;
alter table public.audit_log add constraint audit_log_action_check check (action in ('login', 'logout', 'login_failed', 'reveal_pii', 'open_medical', 'limit_change_request', 'limit_change_approve', 'limit_change_reject', 'claim_transition', 'export', 'role_change', 'user_deactivate', 'hr_add_employee', 'hr_exclude_employee', 'hr_import', 'kp_created', 'kp_sent', 'kp_revoked', 'kp_downloaded', 'clinic_check_patient', 'clinic_check_failed', 'guarantee_requested', 'guarantee_decided', 'registry_submitted', 'registry_line_decided', 'registry_paid', 'integration_key_created', 'integration_key_revoked', 'webhook_created', 'policy_issued', 'policy_change_requested', 'policy_change_decided', 'assistance_assigned', 'case_created', 'guarantee_escalated', 'clinic_payment_recorded', 'rebill_submitted', 'rebill_line_decided', 'rebill_paid', 'qa_reviewed', 'complaint_resolved', 'dms_param_proposed', 'dms_param_changed', 'dms_param_rejected', 'authority_proposed', 'authority_changed', 'authority_rejected', 'lead_created', 'deal_stage_changed', 'deal_lost', 'census_uploaded', 'quote_saved', 'quote_submitted', 'quote_approved', 'quote_rejected', 'kp_accepted', 'kp_declined', 'contract_created', 'contract_updated', 'contract_legal_submitted', 'contract_legal_approved', 'contract_legal_returned', 'contract_finance_approved', 'contract_sent', 'contract_signed', 'contract_scan_uploaded', 'contract_scan_verified', 'contract_original', 'contract_activated', 'contract_terminated', 'contract_expired', 'policy_expired', 'payment_recorded', 'payments_imported', 'payment_allocated', 'change_request_created', 'endorsement_created', 'endorsement_signed', 'claim_opinion_requested', 'claim_opinion_given', 'claim_decided', 'claim_decision_escalated', 'claim_decision_rejected', 'claim_reserve_changed', 'claim_created', 'claim_flag_dismissed', 'claim_appealed', 'claim_appeal_resolved', 'ai_settings_proposed', 'ai_settings_changed', 'ai_settings_rejected', 'ai_kill_switch', 'ai_feedback', 'migration_v